import sys,numpy as np,math
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); init=np.array(r.get_obs(video='none').meta['proprio']['now'][:14]); qa=np.array([0,2**-.5,2**-.5,0.])
def mul(a,b):
 w,x,y,z=a; W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
def solve_path(q,end):
 seed=init.copy(); start=np.array([.485,-.096,.96]); z=r.ik({'Gripper_Tip_R':[*start,*q]},seed=seed)
 if not z['ok']: return 'cardfail', z['error']
 seed=z['q']; prev=start
 # lift first, then transport in XY at high z, then lower at destination
 points=[np.array([.485,-.096,1.08]),np.array([end[0],end[1],1.08]),np.array(end)]
 for dest in points:
  n=max(1,int(np.ceil(np.linalg.norm(dest-prev)/.01)))
  for i in range(1,n+1):
   p=prev+(dest-prev)*i/n
   z=r.ik({'Gripper_Tip_R':[*p,*q]},seed=seed)
   if not z['ok']: return 'fail', (np.round(p,3).tolist(),z['error'])
   seed=z['q']
  prev=dest
 return 'ok',np.round(seed[:7],2).tolist()
for deg in [-30,-15,0,15,30]:
 a=math.radians(deg); q=mul([math.cos(a/2),0,0,-math.sin(a/2)],qa)
 print('\nalpha',deg,'q',np.round(q,3))
 for x in [.64,.66,.68,.70,.72]:
  state,info=solve_path(q,[x,-.28,1.03]); print(x,state,info)
